import heapq
class Solution:
    def kSum(self, nums: List[int], k: int) -> int:
        a = sorted((abs(x) for x in nums), reverse=True)
        base = sum(x for x in nums if x > 0)
        heap = [(-base, 0)]
        seen = {(0, base)}
        for _ in range(k - 1):
            negS, i = heapq.heappop(heap)
            if i < len(a):
                for ns in (negS + a[i], negS):
                    st = (i + 1, -ns)
                    if st not in seen:
                        seen.add(st)
                        heapq.heappush(heap, (ns, i + 1))
        return -heap[0][0]

