class Solution {
public:
    long long kSum(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> a(n);
        long long base = 0;
        for (int i = 0; i < n; i++) {
            a[i] = llabs((long long)nums[i]);
            if (nums[i] > 0) base += nums[i];
        }
        sort(a.rbegin(), a.rend());
        priority_queue<pair<long long,int>> pq;
        pq.push({base, 0});
        unordered_set<long long> seen;
        seen.insert(((long long)0 << 48) | base);
        for (int t = 0; t < k - 1; t++) {
            auto [s, i] = pq.top(); pq.pop();
            if (i < n) {
                long long cands[2] = {s - a[i], s};
                for (long long ns : cands) {
                    long long key = ((long long)(i + 1) << 48) | ns;
                    if (!seen.count(key)) {
                        seen.insert(key);
                        pq.push({ns, i + 1});
                    }
                }
            }
        }
        return pq.top().first;
    }
};

