import java.util.*;
class Solution {
    public long kSum(int[] nums, int k) {
        int n = nums.length;
        long[] a = new long[n];
        long base = 0;
        for (int i = 0; i < n; i++) {
            a[i] = Math.abs((long) nums[i]);
            if (nums[i] > 0) base += nums[i];
        }
        Arrays.sort(a);
        for (int l = 0, r = n - 1; l < r; l++, r--) {
            long t = a[l]; a[l] = a[r]; a[r] = t;
        }
        PriorityQueue<long[]> pq = new PriorityQueue<>((x, y) -> Long.compare(y[0], x[0]));
        Set<Long> seen = new HashSet<>();
        pq.offer(new long[]{base, 0});
        seen.add(0L << 48 | base);
        for (int t = 0; t < k - 1; t++) {
            long[] cur = pq.poll();
            long s = cur[0]; int i = (int) cur[1];
            if (i < n) {
                long[] cands = {s - a[i], s};
                for (long ns : cands) {
                    long key = (long)(i + 1) << 48 | ns;
                    if (seen.add(key)) pq.offer(new long[]{ns, i + 1});
                }
            }
        }
        return pq.peek()[0];
    }
}

