var kSum = function(nums, k) {
    const a = nums.map(Math.abs).sort((x, y) => y - x);
    let base = 0;
    for (const x of nums) if (x > 0) base += x;
    const heap = [[base, 0]];
    const seen = new Set(['0,' + base]);
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let l = 2 * i + 1, r = l + 1, m = i;
                if (l < heap.length && heap[l][0] > heap[m][0]) m = l;
                if (r < heap.length && heap[r][0] > heap[m][0]) m = r;
                if (m === i) break;
                [heap[i], heap[m]] = [heap[m], heap[i]];
                i = m;
            }
        }
        return top;
    };
    const push = (e) => {
        heap.push(e);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p][0] >= heap[i][0]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    };
    for (let t = 0; t < k - 1; t++) {
        const [s, i] = pop();
        if (i < a.length) {
            for (const ns of [s - a[i], s]) {
                const key = (i + 1) + ',' + ns;
                if (!seen.has(key)) {
                    seen.add(key);
                    push([ns, i + 1]);
                }
            }
        }
    }
    return heap[0][0];
};

