        if (n == 1) return k == 1 ? max(nums[0], 0) : 0;
        vector<long long> a(n);
        long long base = 0;
        for (int i = 0; i < n; i++) {
            a[i] = llabs((long long)nums[i]);
            if (nums[i] > 0) base += nums[i];
        }
        sort(a.rbegin(), a.rend());
        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
        pq.push({a[0], 0});
        long long deficit = 0;
        for (int t = 0; t < k - 1; t++) {
            auto [d, i] = pq.top(); pq.pop();
            deficit = d;
            pq.push({d + a[i + 1], i + 1});
            if (i > 0) pq.push({d - a[i] + a[i + 1], i + 1});
        }
        return base - deficit;
    }
};

