import java.util.*;
class Solution {
    public long kSum(int[] nums, int k) {
        int n = nums.length;
        if (n == 1) return k == 1 ? Math.max(nums[0], 0) : 0;
        long[] a = new long[n];
        long base = 0;
        for (int i = 0; i < n; i++) {
            a[i] = Math.abs((long) nums[i]);
            if (nums[i] > 0) base += nums[i];
        }
        Arrays.sort(a);
        for (int l = 0, r = n - 1; l < r; l++, r--) {
            long t = a[l]; a[l] = a[r]; a[r] = t;
        }
        PriorityQueue<long[]> pq = new PriorityQueue<>((x, y) -> Long.compare(x[0], y[0]));
        pq.offer(new long[]{a[0], 0});
        long deficit = 0;
        for (int t = 0; t < k - 1; t++) {
            long[] cur = pq.poll();
            deficit = cur[0];
            int i = (int) cur[1];
            pq.offer(new long[]{cur[0] + a[i + 1], i + 1});
            if (i > 0) pq.offer(new long[]{cur[0] - a[i] + a[i + 1], i + 1});
        }
        return base - deficit;
    }
}

